"""Produce the explicitly reviewed local T29 candidate; no prior release overwrite."""
import pathlib,json,hashlib,subprocess
r=pathlib.Path(__file__).resolve().parents[2];o=r/'test-results/t29';s=pathlib.Path((o/'source-path.txt').read_text());commit='c02ac42859b7140a5e76f7b4126b18973bbdd84f';assert hashlib.sha256((r/'docs/discovery/t29-candidate-plan.md').read_bytes()).hexdigest()=='0ded7d9cce3b3c5fa661864ee08b4df8d1b852211c22a53150dcaf5f1a5dbd5c';assert not(o/'releases').exists();(o/'releases').mkdir();v=json.loads((s/'release.config.json').read_text());v.update(version='0.1.2-t29.1',upgradeFrom=['0.1.0','0.1.1-t28.1']);overlay=o/'release-overlay.json';overlay.write_text(json.dumps(v,indent=2)+'\n');image=subprocess.check_output(['docker','image','inspect','t29-tools','--format','{{.Id}}'],text=True).strip();cmd=['docker','run','--rm','--name','t29-release','-e','TEMPLUX_SOURCE_COMMIT='+commit,'-v',str(overlay)+':/opt/templux/release.config.json:ro','-v',str(o/'releases')+':/release','--entrypoint','sh',image,'-c','cp -R /root/.npm /tmp/t29-npm-cache; export npm_config_cache=/tmp/t29-npm-cache; exec node tools/release/build.mjs /release'];(o/'release-command.json').write_text(json.dumps(cmd,indent=2));f=open(o/'release.log','w');q=subprocess.run(cmd,stdout=f,stderr=subprocess.STDOUT,timeout=300);print('release',q.returncode);assert q.returncode==0
